22. ตอบ 2) It was sought after by collectors.
Why was a lock of Lennon''s hair worth a lot of money ?
ทำไมเส้นผมของ Lennon ถึงมีมูลค่าเป็นเงินมากมาย
1. It was very old. มันเก่ามาก
