Reading 2
The Great Sphinx of Giza in Egypt is a 20.22 meter tall stone figure of a lion with the head
of a human. The structure of the Sphinx is cut entirely out of rock. Some people believe that
there is a hidden area inside which people can enter, but no one has yet found a way to get in.
Many stories have been told about the Great Sphinx as if it were a living creature and had the
human qualities of being strong and wise.
There is one story about a young man who fell asleep next to the Great Sphinx. The man
had gone hunting that day and he was tired. As he slept, the man dreamt that he would become
the King of Egypt if he cleared away the desert sand that was partially covering the Sphinx.
But the story oddly had no ending. What do you think happened? Did the boy clean the
sand away from the Sphinx ? Did he become King of Egypt ? No one seems to know.
Over time, wind and sand have worn away part of the Great Sphinx''s nose as well as other
areas. However, it is now being restored to look much like it once did.
คำแปล :
สฟิงซ์แห่งกิซาในอียิปต์เป็นรูปปั้นหินสูง 20.22 เมตร เป็นรูปสิงโตที่มีหัวเป็นมนุษย์ โครงสร้างของสฟิงซ์
ถูกแกะสลักจากหินทั้งหมด บางคนเชื่อว่ามีพื้นที่ลับอยู่ภายในที่ผู้คนสามารถเข้าไปได้ แต่ยังไม่มีใครค้นพบวิธีเข้าไป
ได้ เรื่องราวมากมายถูกเล่าขานเกี่ยวกับสฟิงซ์ราวกับว่าเป็นสิ่งมีชีวิตที่มีคุณสมบัติของมนุษย์ คือแข็งแกร่งและ
ฉลาด
มีเรื่องเล่าเรื่องหนึ่งเกี่ยวกับชายหนุ่มคนหนึ่งที่เผลอหลับไปข้าง ๆ สฟิงซ์ ชายคนนั้นไปล่าสัตว์มาในวันนั้น
และเขาเหนื่อยล้า ขณะที่เขานอนหลับ ชายคนนั้นฝันว่าเขาจะได้เป็นกษัตริย์แห่งอียิปต์หากเขากวาดทราย
ทะเลทรายที่ปกคลุมสฟิงซ์อยู่บางส่วนออกไป
แต่เรื่องราวนี้กลับไม่มีตอนจบที่แปลกประหลาด คุณคิดว่าเกิดอะไรขึ้น ? เด็กหนุ่มคนนั้นกวาดทรายออก
จากสฟิงซ์ได้หรือไม่ ? เขาได้เป็นกษัตริย์แห่งอียิปต์หรือไม่ ? ดูเหมือนจะไม่มีใครรู้
เมื่อเวลาผ่านไป ลมและทรายได้กัดกร่อนส่วนหนึ่งของจมูกของมหาสฟิงซ์ รวมถึงส่วนอื่น ๆ ด้วย อย่างไร
ก็ตาม ขณะนี้กำลังมีการบูรณะเพื่อให้ดูเหมือนเดิมมากที่สุดเท่าที่จะเป็นไปได้

24. ตอบ 4) A statue
What is the story mainly about ? ใจความสำคัญของเรื่องคืออะไร
1. A lion สิงโต
2. An animal สัตว์
3. A king กษัตริย์
4. A statue รูปปั้น' WHERE id = '2559_Paper_117';
