ทะเลทรายที่ปกคลุมสฟิงซ์อยู่บางส่วนออกไป
แต่เรื่องราวนี้กลับไม่มีตอนจบที่แปลกประหลาด คุณคิดว่าเกิดอะไรขึ้น ? เด็กหนุ่มคนนั้นกวาดทรายออก
