23. ตอบ 2) Keep a minimum sum of money in the account
What must customers do to avoid a service charge ? ลูกค้าต้องทำอะไรเพื่อหลีกเลี่ยงค่าบริการ
1. Make less than thirty withdrawals a year ถอนเงินไม่เกิน 30 ครั้ง/ปี
2. Keep a minimum sum of money in the account รักษายอดเงินขั้นต่ำในบัญชี
3. Maintain the account for at least five years รักษาบัญชีไว้อย่างน้อย 5 ปี
4. Have more than one account at the bank มีบัญชีมากกว่าหนึ่งบัญชีที่ธนาคารเดียวกัน' WHERE id = '2561_Paper_085';
UPDATE questions SET explanation = 'ข้อสอบจริง ก.พ. ปี 2561 ชุด Paper

