สถานการณ์: สัมภาษณ์งาน
David | Good morning Miss Lee. My name is David Fort. I am the marketing Department Manager. Please have a seat. | สวัสดี Miss Lee. ฉันชื่อ David Fort. ฉันเป็นผู้จัดการฝ่ายการตลาด. นั่งก่อนสิ.
Miss Lee | Thank you, sir ____(6)_____. | ขอบคุณมาก, ____(6)_____.
David | Nice to meet you too. First of all, could you please ___(7)_____? | ยินดีที่ได้รู้จักเช่นกัน. ก่อนอื่น คุณช่วย ___(7)_____?
Miss Lee | I graduated from Lancaster University with master’s degree in marketing. I used to work part-time as market research assistant in an insurance company. In my last position, I was a market researcher at M. bank. | ฉันจบมหาวิทยาลัย Lancaster ระดับ ปริญญาโท สาขาการตลาด. ฉันเคยทำงานพาร์ทไทม์เป็นผู้ช่วยทำวิจัย การตลาดในบริษัทประกันภัย. งานล่าสุดที่ฉันทำคือเป็นนักวิจัยการตลาดที่ ธนาคาร M
David | I am very impressed with your resume. I just wonder ___(8)_____. | ฉันประทับใจเรซูเม่ของคุณมาก. ฉันแค่สังสัย ___(8)_____.
Miss Lee | Honestly, I want to gain more experience in a bigger organization. | ฉันต้องการประสบการณ์ที่มากขึ้นในองค์กร ที่ใหญ่กว่าเดิม
David | I see. So, what skill or talents do you have that will be useful for the position of market researcher. | ฉันเข้าใจแล้ว, คุณมีทักษะหรือ ความสามารถอะไรที่จะเป็นประโยชน์ใน การทำงานตำแหน่งนักวิจัยการตลาด
Miss Lee | ____(9)____. | ____(9)____.
David | That’s good to hear. ___(10)_____? | ฟังดูดีนะ ___(10)_____?
Miss Lee | No, not at all. The last job required me to work overtime sometime and I could handle it. | ไม่, ไม่ใช่ทั้งหมด. งานล่าสุดต้องการให้ฉันทำงานเกินเวลา บางครั้ง และฉันก็สามารถทำได้

6. ตอบ 3) It’s nice to meet you.
1. I can sit here. ฉันสามารถนั่งตรงนี้
2. You look so nice. คุณดูดีนะ
3. It’s nice to meet you. ยินดีที่ได้เจอ
4. Your room is very nice. ห้องคุณดูดีนะ' WHERE id = '2562_Paper_083';
UPDATE questions SET explanation = 'ข้อสอบจริง ก.พ. ปี 2562 ชุด Paper

