จงอ่านบทสนทนาต่อไปนี้และตอบคำถามข้อ 6 - 10
บริกร Hello, . . . (6) . . . สวัสดี, . . . .
ลูกค้า Yes, I would like to have some lunch. ใช่, ฉันต้องการรับประทานอาหารกลางวัน
บริกร Great, would you like to order now ? เยี่ยมเลย, คุณจะสั่งอาหารตอนนี้เลยไหม
ลูกค้า Yes, . . . (7) . . .. Is the spicy soup good ? ใช่, . . . . ซุปเผ็ดเป็นยังไงบ้าง ดีไหม
