ลูกค้า Yes, a coke please. ใช่, รบกวนขอโค้กให้ฉันด้วย
บริกร . . . (9) . . . I can do for you ? . . . . ฉันสามารถทำให้คุณได้
ลูกค้า Yes, I would like a dessert please. . . . . ใช่, ฉันอยากได้ของหวาน . . . . ?
(10). . . ?
