Reading 1
October 10, 2020
Customer Service Department
Flexco Woman''s Clothing
234502 Anthony Place
Woodston, NY 12229
Dear Customer Service,
I am writing to express my extreme dissatisfaction with a recent purchase of a Flexco garment.
Last week I went to our local department store to buy a gift for my wife. I chose a very handsome
Flexco raincoat and gave it to my wife on her birthday last Sunday. She was pleased with the gift
and wore it yesterday because we had a big rainstorm. We were both surprised to find out that
the raincoat is not water repellant at all. My wife returned from her walk very, very wet. In
addition, the fabric of the coat became wrinkled in the rain. I bought the Flexco raincoat for my
wife because Flexco is one of her favorite brands. She already owns several Flexco dresses, skirts,
and blouses. We never expected to be disappointed by a Flexco product.
I took the raincoat back to the store this morning. The manager there said that he did not see
any defects in the coat, but he offered me a different coat in exchange. Since I understand that
Flexco guarantees a complete refund on all its products, I did not accept the manager''s offer. I
hope that Flexco will stand by its guarantee. I am returning the raincoat with this letter, together
with the receipt from the department store, and hope to receive a complete refund before the
end of the month. Thank you for your attention to this matter.
Sincerely,
Thomas Jamison
คำแปล (เฉพาะเนื้อหาจดหมาย) :
เรียน ฝ่ายบริการลูกค้า
ฉันเขียนจดหมายฉบับนี้เพื่อแสดงความไม่พอใจอย่างยิ่งต่อสินค้า Flexco ที่ฉันเพิ่งซื้อไปเมื่อสัปดาห์ที่แล้ว ฉันไป
ห้างสรรพสินค้าใกล้บ้านเพื่อซื้อของขวัญให้ภรรยา ฉันเลือกเสื้อกันฝน Flexco ที่ดูดีมากตัวหนึ่งและมอบให้ภรรยา
ในวันเกิดของเธอเมื่อวันอาทิตย์ที่ผ่านมา เธอพอใจกับของขวัญชิ้นนี้และสวมใส่เมื่อวานนี้เพราะมีพายุฝนตกหนัก
เราทั้งคู่ต่างประหลาดใจที่พบว่าเสื้อกันฝนนั้นไม่กันน้ำเลย ภรรยาของฉันกลับมาจากการเดินเล่นในสภาพที่เปียก
โชก นอกจากนี้ ผ้าของเสื้อกันฝนยังยับย่นเพราะฝนตกอีกด้วย ฉันซื้อเสื้อกันฝน Flexco ให้ภรรยาเพราะ Flexco
เป็นหนึ่งในแบรนด์โปรดของเธอ เธอมีชุดเดรส กระโปรง และเสื้อเบลาส์ Flexco หลายชิ้นอยู่แล้ว เราไม่เคย
คาดหวังว่าจะผิดหวังกับสินค้า Flexco เลย
ฉันนำเสื้อกันฝนกลับไปที่ร้านในเช้าวันนี้ ผู้จัดการที่นั่นบอกว่าเขาไม่เห็นข้อบกพร่องใด ๆ ในเสื้อกันฝน แต่เขา
เสนอเสื้อกันฝนตัวใหม่ให้แลกเปลี่ยน เนื่องจากฉันเข้าใจว่า Flexco รับประกันคืนเงินเต็มจำนวนสำหรับสินค้าทุก
ชิ้น ฉันจึงไม่รับข้อเสนอของผู้จัดการ ฉันหวังว่า Flexco จะปฏิบัติตามการรับประกันของตน ฉันกำลังส่งคืนเสื้อกัน
ฝนพร้อมกับจดหมายฉบับนี้ และใบเสร็จรับเงินจากห้างสรรพสินค้า โดยหวังว่าจะได้รับเงินคืนเต็มจำนวนก่อนสิ้น
เดือนนี้ ขอขอบคุณสำหรับความเอาใจใส่ในเรื่องนี้
ด้วยความเคารพ
Thomas Jamison

32. ตอบ 2) He is unhappy with his purchase.
Why did Mr. Jamison write this letter ? ทำไม Mr. Jamison ถึงเขียนจดหมาย
1. He wants to order more garments from Flexco. เขาต้องการสั่งซื้อเสื้อผ้าจาก Flexco เพิ่ม
2. He is unhappy with his purchase. เขารู้สึกไม่พอใจกับการซื้อสินค้าของเขา
3. He is looking for a present for his wife. เขากำลังมองหาของขวัญให้ภรรยา
4. He wants to express his appreciation of Flexco products.
เขาต้องการแสดงความขอบคุณต่อผลิตภัณฑ์ของ Flexco' WHERE id = '2565_Paper_108';
UPDATE questions SET explanation = 'ข้อสอบจริง ก.พ. ปี 2565 ชุด Paper

