Reading 2
Barn owls, of the family Tytonidae, are anatomically different enough from other owls to
merit their own family in the order Strigiformes. Instead of the more or less rounded face of most
owls, the barn owl has a heart-shaped face and lacks the usual tufted earlike feathers. The
common barn owl is from 12 to 18 inches long and has a white face, cinnamon buff back, buff
or white breast, and relatively small eyes. The legs are fairly long, feathered to the toes, and, like
those of all owls, very strong and equipped with sharp, powerful, curved claws, the outer ones
being reversible, although they are usually directed backward.
Barn owls nest in hollow trees, caves, and buildings on every continent except Antarctica
and have adapted so well to living near humans that in some areas they seem to have forsaken
natural nesting places in favor of man-made ones. They hunt in open spaces and have the largest
range of any nocturnal bird. They use their eyesight to locate prey, but their hearing is so highly
developed that they can hunt small mammals in total darkness. Barn owls are economically
valuable because of their preference for small, crop-destroying mammals.
คำแปล :
นกฮูกยุ้งฉาง (Barn owl) ในวงศ์ Tytonidae มีลักษณะทางกายวิภาคแตกต่างจากนกฮูกชนิดอื่นมาก
พอที่จะจัดอยู่ในวงศ์ของตัวเองในอันดับ Strigiformes แทนที่จะมีใบหน้ากลมเหมือนนกฮูกส่วนใหญ่ นกฮูกยุ้งฉาง
มีใบหน้ารูปหัวใจและไม่มีขนเป็นกระจุกคล้ายหูเหมือนนกฮูกทั่วไป นกฮูกยุ้งฉางทั่วไปมีความยาว 12 ถึง 18 นิ้ว มี
ใบหน้าสีขาว หลังสีน้ำตาลอมเหลือง อกสีเหลืองอ่อนหรือขาว และดวงตาค่อนข้างเล็ก ขาค่อนข้างยาว มีขนปก
คลุมถึงนิ้วเท้า และเช่นเดียวกับนกฮูกทุกชนิด ขาแข็งแรงมากและมีกรงเล็บที่แหลมคม แข็งแรง และโค้งงอ กรง
เล็บด้านนอกสามารถกลับด้านได้ แม้ว่าโดยปกติแล้วจะชี้ไปด้านหลัง
นกฮูกยุ้งฉางทำรังในโพรงต้นไม้ ถ้ำ และอาคารในทุกทวีปยกเว้นทวีปแอนตาร์กติกา และปรับตัวได้ดีมาก
ในการอาศัยอยู่ใกล้กับมนุษย์ จนในบางพื้นที่ดูเหมือนว่าพวกมันจะละทิ้งสถานที่ทำรังตามธรรมชาติเพื่อไปทำรังใน
สถานที่ที่มนุษย์สร้างขึ้นแทน พวกมันออกล่าในพื้นที่โล่ง และมีอาณาเขตหากินกว้างที่สุดในบรรดานกกลางคืน
ทั้งหมด พวกมันใช้สายตาในการหาเหยื่อ แต่การได้ยินของพวกมันพัฒนาอย่างมากจนสามารถล่าสัตว์เลี้ยงลูกด้วย
นมขนาดเล็กได้ในความมืดสนิท นกฮูกยุ้งฉางมีคุณค่าทางเศรษฐกิจเนื่องจากพวกมันชอบล่าสัตว์เลี้ยงลูกด้วยนม
ขนาดเล็กที่ทำลายพืชผลทางการเกษตร

